'use strict';
// Synthetic read-only reconciliation. Never posts trades, releases reserves or closes incidents.
const reconciliationStatuses={unchecked:['Не проверено','Not checked'],missing:['Недостаточно данных','Insufficient evidence'],matched:['Снимок совпадает','Snapshot matches'],difference:['Есть расхождение','Difference found']};
const reconciliationFixtures=[
 {id:'REC-101',key:'noor',uid:'U-DEMO-002',sid:'S-DEMO-002',oid:'ORD-002',incident:'INC-101',name:'Demo Noor',venue:'Polymarket',date:'2026-10-23',cutoff:'2026-10-23 12:00 UTC',source:'DEMO-ORDER-002',field:['Исполнение заявки','Order fill'],recorded:null,observed:null,reserve:20,reason:['Нет подтверждённого итога исходной заявки. Нулевое исполнение не доказано.','No confirmed outcome for the original order. Zero fill is not established.'],next:['Дождаться подтверждения исходной заявки и повторить сверку. Повторная отправка недоступна.','Wait for original-order evidence, then recheck. Resending remains unavailable.']},
 {id:'REC-102',key:'orion',uid:'U-DEMO-009',sid:'S-DEMO-009',oid:'ORD-009',incident:'INC-102',name:'Demo Orion',venue:'Limitless',date:'2026-10-23',cutoff:'2026-10-23 10:20 UTC',source:'DEMO-SNAPSHOT-009',field:['Стоимость позиций по учёту','Position cost basis'],recorded:20,observed:24,reserve:20,reason:['Контрольный пример: два учебных источника одного исторического снимка расходятся на 4 USD. Текущие суммы не подтверждены.','Control example: two synthetic sources for the same historical snapshot differ by USD 4. Current amounts are unconfirmed.'],next:['Разобрать подтверждающие записи в INC-102. Не исправлять сумму вручную и не считать восстановление потока исправлением учёта.','Investigate evidence in INC-102. Do not manually overwrite amounts or equate feed recovery with correcting the ledger.']},
 {id:'REC-103',key:'robin',uid:'U-DEMO-005',sid:'S-DEMO-005',oid:'ORD-005',incident:'INC-103',name:'Demo Robin',venue:'Limitless',date:'2026-10-22',cutoff:'2026-10-22 12:00 UTC',source:'DEMO-FILL-005',field:['Исполнение заявки','Order fill'],recorded:8,observed:8,reserve:12,reason:['Подтверждённая часть совпала: 8 USD из 20 USD. Отмена остатка 12 USD ещё не подтверждена.','Confirmed fill matches: USD 8 of USD 20. Cancellation of the USD 12 remainder is still unconfirmed.'],next:['Продолжать наблюдение за остатком заявки. Совпадение этой части не завершает всю денежную сверку.','Continue observing the order remainder. Matching this part does not complete full monetary reconciliation.']}
];
function newReconciliation(){return {records:structuredClone(reconciliationFixtures).map(x=>({...x,version:1,result:'unchecked',runs:[],note:'',notes:[]})),id:'REC-101',q:'',status:'all',venue:'all',from:'2026-10-17',to:'2026-10-23',sort:'newest',error:null,returnIncident:false,returnContext:false,scroll:0};}
let reconciliation=newReconciliation();
const reconciliationAccess=()=>({read:!!account?.logged&&supportAccess(state.role).read,money:!!account?.logged&&actor().money,run:!!account?.logged&&actor().money&&supportAccess(state.role).write});
const reconciliationAllowed=x=>reconciliationAccess().read&&(!actor().limited||x.uid==='U-DEMO-002');
const reconciliationCurrent=()=>reconciliation.records.find(x=>x.id===reconciliation.id&&reconciliationAllowed(x));
const rb=(ru,en,a,extra='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-reconciliation="${a}" ${extra}>${pl(ru,en)}</button>`;
const reconciliationValue=v=>!reconciliationAccess().money?pl('Нет доступа к сумме','Amount access restricted'):v===null?pl('Не подтверждено','Unconfirmed'):new Intl.NumberFormat(state.locale==='ru'?'ru-RU':'en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v)+' USD';
function reconciliationRows(){const q=reconciliation.q.trim().toLowerCase();return reconciliation.records.filter(x=>reconciliationAllowed(x)&&(!q||[x.id,x.uid,x.sid,x.oid,x.incident,x.name].join(' ').toLowerCase().includes(q))&&(reconciliation.status==='all'||x.result===reconciliation.status)&&(reconciliation.venue==='all'||x.venue===reconciliation.venue)&&x.date>=reconciliation.from&&x.date<=reconciliation.to).sort((a,b)=>a.date.localeCompare(b.date)*(reconciliation.sort==='oldest'?1:-1));}
const reconciliationResult=x=>x.recorded===null||x.observed===null?'missing':x.recorded===x.observed?'matched':'difference';
function reconciliationRun(expectedVersion){const x=reconciliationCurrent();if(!x||!reconciliationAccess().run)return false;if(expectedVersion!==x.version){reconciliation.error=['Снимок изменился. Откройте запись заново и проверьте новую версию.','The snapshot changed. Reopen the record and review its new version.'];return false;}x.result=reconciliationResult(x);x.runs.push({version:x.version,source:x.source,cutoff:x.cutoff,result:x.result,author:accountName()+' · '+actor().id,time:new Date().toISOString()});return true;}
function reconciliationList(){if(!reconciliationAccess().read)return incidentDenied();const rows=reconciliationRows();return supportHeading(pl('Денежная сверка','Money reconciliation'),pl('Сравните учёт с подтверждающими данными. Разберите расхождение через связанный инцидент.','Compare recorded amounts with supporting evidence. Investigate differences through the linked incident.'))+`<p class="support-notice">${pl('Демо-торговля · виртуальные USD · комиссия Shadow 0%. Суммы разных площадок не складываются.','Demo trading · virtual USD · Shadow fee 0%. Amounts from different venues are not combined.')}</p><section class="panel support-filters"><div class="field"><label for="reconciliation-q">${pl('Пользователь, заявка или ID','User, order or ID')}</label><input id="reconciliation-q" type="search" value="${escape(reconciliation.q)}"></div>${feedbackSelect('reconciliation-status',pl('Результат проверки','Check result'),[['all',pl('Все результаты','All results')],...Object.entries(reconciliationStatuses).map(([k,v])=>[k,pl(...v)])],reconciliation.status)}${feedbackSelect('reconciliation-venue',pl('Площадка','Venue'),[['all',pl('Все площадки','All venues')],['Polymarket','Polymarket'],['Limitless','Limitless']],reconciliation.venue)}${['from','to'].map(k=>`<div class="field"><label for="reconciliation-${k}">${k==='from'?pl('С даты снимка · UTC','Snapshot from · UTC'):pl('По дату · UTC','Through · UTC')}</label><input id="reconciliation-${k}" type="date" value="${reconciliation[k]}"></div>`).join('')}${rb('Сбросить фильтры','Reset filters','reset')}${reconciliation.error?`<p role="alert">${pl(...reconciliation.error)}</p>`:''}</section><section class="panel"><div class="support-table-top"><h2>${pl('Проверки','Checks')} · ${rows.length}</h2>${feedbackSelect('reconciliation-sort',pl('Порядок','Sort'),[['newest',pl('Сначала новые','Newest first')],['oldest',pl('Сначала старые','Oldest first')]],reconciliation.sort)}</div><div class="table-wrap"><table class="reconciliation-table"><thead><tr>${[['Проверка / пользователь','Check / user'],['Площадка','Venue'],['Показатель','Measure'],['Результат','Result'],['Разница · USD','Difference · USD'],['Снимок · UTC','Snapshot · UTC']].map(v=>`<th scope="col">${pl(...v)}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td>${rb(x.id,x.id,'open',`data-id="${x.id}"`)}<small>${x.name}<br>${x.oid} · ${x.incident}</small></td><td>${x.venue}</td><td>${pl(...x.field)}</td><td><span class="badge ${['missing','difference'].includes(x.result)?'warn':''}">${pl(...reconciliationStatuses[x.result])}</span></td><td class="num">${x.result==='unchecked'?pl('Ещё не рассчитана','Not calculated'):reconciliationValue(x.recorded===null||x.observed===null?null:x.observed-x.recorded)}</td><td>${x.cutoff}</td></tr>`).join('')}</tbody></table></div>${rows.length?'':`<div class="empty"><h2>${pl('Нет проверок по этому отбору','No matching checks')}</h2>${rb('Сбросить фильтры','Reset filters','reset')}</div>`}</section><p class="muted">${pl('Три учебных снимка. Проверка ничего не отправляет и не исправляет учёт.','Three synthetic snapshots. Checking neither sends operations nor corrects the ledger.')}</p>`;}
function reconciliationDetail(){const x=reconciliationCurrent();if(!x)return incidentDenied();const a=reconciliationAccess(),delta=x.recorded===null||x.observed===null?null:x.observed-x.recorded;return rb('К списку сверки','Back to reconciliation','back')+supportHeading(pl('Проверка денежных данных','Check monetary evidence'),`${x.id} · ${x.name} · ${x.venue} · ${pl('Демо','Demo')}`)+`<div class="support-layout reconciliation-workbench"><div><section class="panel"><h2>${pl(...x.field)}</h2><p class="muted">${pl('Один снимок и одна область','One snapshot and one scope')}: ${x.cutoff}<br>${x.uid} · ${x.sid} · ${x.oid}</p><div class="table-wrap"><table class="reconciliation-comparison"><thead><tr><th>${pl('По учёту Shadow','Shadow record')}</th><th>${pl('По учебному подтверждению','Synthetic evidence')}</th><th>${pl('Разница: подтверждение − учёт','Difference: evidence − record')}</th></tr></thead><tbody><tr>${[x.recorded,x.observed,x.result==='unchecked'?null:delta].map(v=>`<td class="reconciliation-amount">${reconciliationValue(v)}</td>`).join('')}</tr></tbody></table></div><p>${pl('Виртуальные USD, не баланс кошелька и не прибыль.','Virtual USD, not a wallet balance or profit.')}</p><details><summary>${pl('Как считается разница?','How is the difference calculated?')}</summary><p>${pl('Вычитаем учтённую сумму из подтверждённой только для того же показателя, снимка, площадки и валюты. Если подтверждения нет, разница неизвестна, а не равна нулю.','Subtract the recorded amount from evidence only for the same measure, snapshot, venue and currency. Missing evidence means an unknown difference, not zero.')}</p></details></section><section class="panel"><h2>${pl('Результат проверки','Check result')}</h2><p class="incident-impact">${pl(...reconciliationStatuses[x.result])}</p>${x.result==='unchecked'?`<p>${pl('Сравните подготовленные данные этого снимка. Проверка не запрашивает площадку.','Compare the prepared evidence for this snapshot. This does not query the venue.')}</p>`:`<p>${a.money?pl(...x.reason):pl('Подробности сумм недоступны в этом назначении.','Amount details are restricted in this assignment.')}</p>`}${a.run?rb(x.runs.length?'Повторить проверку снимка':'Проверить снимок',x.runs.length?'Recheck snapshot':'Check snapshot','run',`data-version="${x.version}"`,true):`<p>${pl('Только просмотр. Проверка и внутренние заметки недоступны.','Read only. Running checks and internal notes are unavailable.')}</p>`}${reconciliation.error?`<p class="account-error" role="alert">${pl(...reconciliation.error)}</p>`:''}<p class="muted">${pl('Это результат для выбранного показателя. Комиссии площадки, все операции и окончательный остаток здесь не подтверждаются.','This result covers the selected measure. Venue fees, all operations and the final remainder are not certified here.')}</p></section><section class="panel"><h2>${pl('Подтверждающие данные','Supporting evidence')}</h2><dl class="feedback-meta"><dt>${pl('Источник','Source')}</dt><dd>${x.source} · ${pl('учебный снимок','synthetic snapshot')}</dd><dt>${pl('На момент','As of')}</dt><dd>${x.cutoff}</dd><dt>${pl('Версия','Version')}</dt><dd>${x.version}</dd><dt>${pl('Резерв сессии в снимке','Session reserve in snapshot')}</dt><dd>${reconciliationValue(x.reserve)}</dd></dl><p>${pl('Повторная проверка читает тот же снимок; новые данные сами не появляются.','Rechecking reads the same snapshot; it does not fetch new evidence.')}</p></section>${a.run?`<section class="panel"><h2>${pl('Внутренняя заметка','Internal note')}</h2><label for="reconciliation-note">${pl('Что нужно проверить дальше','What to investigate next')}</label><textarea id="reconciliation-note" rows="3" maxlength="2000">${escape(x.note)}</textarea>${rb('Добавить заметку','Add note','note')}${x.notes.map(n=>`<article class="support-message internal"><strong>${escape(n.author)}</strong><p>${escape(n.body)}</p></article>`).join('')}</section>`:''}<details class="panel"><summary>${pl('История проверок','Check history')} · ${x.runs.length}</summary>${x.runs.map(r=>`<p>${escape(r.author)} · ${r.time}<br>${r.source} · v${r.version} · ${pl(...reconciliationStatuses[r.result])}</p>`).join('')||`<p>${pl('Проверок ещё нет.','No checks yet.')}</p>`}</details></div><aside class="support-context"><section class="panel"><h2>${pl('Следующий шаг','Next step')}</h2><p>${pl(...x.next)}</p>${rb('Инцидент '+x.incident,'Incident '+x.incident,'incident')}<p class="muted">${pl('Закрытие инцидента и результат сверки независимы.','Incident closure and reconciliation results are independent.')}</p></section><section class="panel"><h2>${pl('Что не меняется','What stays unchanged')}</h2><p>${pl('Проверка не отправляет заявку повторно, не освобождает резерв, не меняет баланс и не снимает ограничения.','Checking does not resend orders, release reserves, change balances or lift restrictions.')}</p><p>${pl('При техническом режиме разрешена только безопасная проверка уже отправленного.','During maintenance mode, only safe verification of previously submitted operations is allowed.')}</p></section><section class="panel"><h2>${pl('Связанные записи','Related records')}</h2>${rb('Открыть пользователя','Open user','user')}${rb('Открыть сессию','Open session','session')}${rb('Открыть заявку','Open order','order')}</section></aside></div>`;}
function reconciliationAction(a,el={dataset:{}}){reconciliation.error=null;if(a==='open'){const x=reconciliation.records.find(x=>x.id===el.dataset.id&&reconciliationAllowed(x));if(!x)return;reconciliation.id=x.id;reconciliation.returnIncident=false;reconciliation.returnContext=false;reconciliation.scroll=window.scrollY;navigate('reconciliationItem');return;}if(a==='reset'){Object.assign(reconciliation,{q:'',status:'all',venue:'all',from:'2026-10-17',to:'2026-10-23'});render();document.querySelector('[data-reconciliation="reset"]')?.focus();const live=document.querySelector('#announcer');if(live)live.textContent=pl('Фильтры сброшены.','Filters reset.');return;}if(a==='back'){reconciliation.returnIncident=false;reconciliation.returnContext=false;navigate('reconciliation');window.scrollTo(0,reconciliation.scroll);return;}const x=reconciliationCurrent();if(!x)return;if(a==='return'){reconciliation.returnContext=false;reconciliation.returnIncident=false;navigate('reconciliationItem');return;}if(a==='incident'){const i=incidents.records.find(i=>i.id===x.incident&&incidentAllowed(i)&&i.uid===x.uid&&i.sid===x.sid&&i.venue===x.venue);if(!i)return;incidents.id=i.id;incidents.returnTicket=false;incidents.returnContext=false;reconciliation.returnIncident=true;navigate('incident');return;}if(['user','session','order'].includes(a)){reconciliation.returnContext=true;incidents.returnContext=false;support.linked=false;feedback.linkedContext=false;state.userId=x.uid;state.sessionId=x.sid;state.tab='overview';navigate(a);return;}if(!reconciliationAccess().run)return;if(a==='run')reconciliationRun(Number(el.dataset.version));if(a==='note'){if(!x.note.trim())reconciliation.error=['Введите текст заметки.','Enter a note.'];else{x.notes.push({author:accountName()+' · '+actor().id,body:x.note.trim()});x.note='';}}render();if(a==='run'||a==='note'){const target=a==='run'?'[data-reconciliation="run"]':reconciliation.error?'#reconciliation-note':'[data-reconciliation="note"]';document.querySelector(target)?.focus();const announcer=document.querySelector('#announcer');if(announcer)announcer.textContent=reconciliation.error?pl(...reconciliation.error):a==='run'?pl(...reconciliationStatuses[x.result]):pl('Внутренняя заметка добавлена.','Internal note added.');}}
function reconciliationIncidentLinks(){const i=incidentCurrent();if(!i)return '';return reconciliation.records.filter(x=>reconciliationAllowed(x)&&x.incident===i.id&&x.uid===i.uid&&x.sid===i.sid&&x.venue===i.venue).map(x=>rb(reconciliation.returnIncident&&x.id===reconciliation.id?'Вернуться к сверке':'Сверка '+x.id,reconciliation.returnIncident&&x.id===reconciliation.id?'Back to reconciliation':'Reconciliation '+x.id,'open',`data-id="${x.id}"`)).join('');}
function reconciliationReturnAvailable(){const x=reconciliationCurrent();return reconciliation.returnContext&&!!x&&state.userId===x.uid&&(!['session','order'].includes(state.route)||state.sessionId===x.sid);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-reconciliation]');if(b&&!b.disabled)reconciliationAction(b.dataset.reconciliation,b);});
document.addEventListener('input',e=>{if(e.target.id==='reconciliation-note'&&reconciliationCurrent()&&reconciliationAccess().run)reconciliationCurrent().note=e.target.value;if(e.target.id==='reconciliation-q'){reconciliation.q=e.target.value;const p=e.target.selectionStart;render();const n=document.querySelector('#reconciliation-q');n.focus();if(p!==null)n.setSelectionRange(p,p);}});
document.addEventListener('change',e=>{const k=e.target.id.replace('reconciliation-','');if(!e.target.id.startsWith('reconciliation-')||!['status','venue','from','to','sort'].includes(k))return;const v=e.target.value;if(['from','to'].includes(k)&&(!v||(k==='from'?v>reconciliation.to:v<reconciliation.from))){reconciliation.error=['Проверьте порядок дат.','Check date order.'];render();document.querySelector('#reconciliation-'+k)?.focus();return;}reconciliation[k]=v;reconciliation.error=null;render();document.querySelector('#reconciliation-'+k)?.focus();const live=document.querySelector('#announcer');if(live)live.textContent=pl('Найдено проверок: ','Matching checks: ')+reconciliationRows().length;});
